<span class="line"><span class="line"><span style="color:#4D4D4D;font-weight:bold;">|</span><span style="color:#D4D4D4;"> </span><span style="color:#CCCCCC;">when</span><span style="color:#D4D4D4;"> $</span><span style="color:#B48EAD;font-style:italic;">BATTERIES</span><span style="color:#D4D4D4;"> </span><span style="color:#B48EAD;font-style:italic;">critical</span><span style="color:#4D4D4D;font-weight:bold;">;</span></span></span>
